from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(2, 8))
    mode = draw(st.integers(0, 3))
    if mode == 0:
        # all equal values
        v = draw(st.integers(1, 10**8))
        k = [v] * n
    elif mode == 1:
        # small values with duplicates
        k = draw(st.lists(st.integers(1, 5), min_size=n, max_size=n))
    elif mode == 2:
        # extremes of the range
        k = draw(st.lists(st.sampled_from([1, 2, 10**8, 10**8 - 1]), min_size=n, max_size=n))
    else:
        # arbitrary values in range
        k = draw(st.lists(st.integers(1, 10**8), min_size=n, max_size=n))
    if draw(st.booleans()):
        k = sorted(k)
    if draw(st.booleans()):
        k = sorted(k, reverse=True)
    return f"{n}\n{' '.join(map(str, k))}\n"

