    try:
        t = inp.split()
        if len(t) < 1:
            return False
        n = int(t[0])
        if not (2 <= n <= 20):
            return False
        if len(t) != n + 1:
            return False
        k = [int(x) for x in t[1:]]
        return all(1 <= x <= 10**8 for x in k)
    except Exception:
        return False

def ref(inp):
    t = inp.split()
    n = int(t[0])
    k = [int(x) for x in t[1:1 + n]]
    total = sum(k)
    best = None
    for mask in range(1 << n):
        a = 0
        for i in range(n):
            if mask >> i & 1:
                a += k[i]
        b = total - a
        m = max(a, b)
        if best is None or m < best:
            best = m
    return str(best)
